using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Threading;
using Mori;

namespace MoriDesk {
 public static class DocumentContentTests {
  static Exception Failure(Action action){try{action();return null;}catch(Exception ex){return ex;}}
  static void Package(string path,params string[] pairs){
   using(var file=new FileStream(path,FileMode.Create,FileAccess.Write))using(var zip=new ZipArchive(file,ZipArchiveMode.Create))
    for(int i=0;i<pairs.Length;i+=2){var entry=zip.CreateEntry(pairs[i],CompressionLevel.Optimal);using(var writer=new StreamWriter(entry.Open(),new UTF8Encoding(false)))writer.Write(pairs[i+1]);}
  }
  static string Read(string path){return DocumentContent.Read(path,CancellationToken.None).Text;}
  public static void Run(string root,Action<bool,string> check){
   string fixtures=Path.Combine(root,"document-content");Directory.CreateDirectory(fixtures);
   foreach(string extension in new[]{".txt",".md",".markdown",".log",".json",".xml",".yaml",".yml",".ini",".csv",".tsv",".docx",".xlsx",".pptx",".odt",".ods",".odp"})check(DocumentContent.Supports(extension)&&DocumentContent.Supports("C:\\folder\\sample"+extension.ToUpperInvariant()),"content support routes "+extension+" case insensitively");
   foreach(string extension in new[]{".html",".htm",".js",".exe",".docm",".xlsm",".pptm",".doc",".xls",".ppt",".pdf",".rtf"})check(!DocumentContent.Supports(extension),"content reader does not imply unsupported or executable format "+extension);
   check(!DocumentContent.Supports(null)&&!DocumentContent.Supports(""),"content format matching tolerates empty values");
   string text=Path.Combine(fixtures,"hello.TXT");File.WriteAllText(text,"Hello 中文 한글\r\nSecond line",new UTF8Encoding(false));var original=File.ReadAllBytes(text);var result=DocumentContent.Read(text,CancellationToken.None);
   check(result.Text=="Hello 中文 한글\r\nSecond line"&&!result.Truncated&&result.EncodingName=="utf-8","BOM-less UTF-8 retains multilingual text");
   check(result.Kind=="TXT"&&result.SourcePath==Path.GetFullPath(text)&&result.Limitation.Contains("不执行"),"content result describes source and non-executing preview");
   check(original.SequenceEqual(File.ReadAllBytes(text)),"content preview never modifies the original text file");
   Encoding[] encodings={new UTF8Encoding(true),new UnicodeEncoding(false,true),new UnicodeEncoding(true,true),new UTF32Encoding(false,true),new UTF32Encoding(true,true)};
   foreach(var encoding in encodings){string encoded=Path.Combine(fixtures,"encoding-"+encoding.CodePage+".txt");File.WriteAllText(encoded,"A 中文 Ω 🐱 B",encoding);check(Read(encoded)=="A 中文 Ω 🐱 B","BOM decoding preserves "+encoding.WebName);}
   string noBom=Path.Combine(fixtures,"no-bom.txt");File.WriteAllBytes(noBom,Encoding.Unicode.GetBytes("Plain UTF sixteen text and more"));check(Read(noBom)=="Plain UTF sixteen text and more","BOM-less UTF-16 ASCII patterns are detected");
   string legacy=Path.Combine(fixtures,"legacy.txt");string legacyText=Encoding.Default.CodePage==936?"旧版中文 文档":Encoding.Default.CodePage==65001?"Legacy UTF8 café":"Legacy café Windows text";File.WriteAllText(legacy,legacyText,Encoding.Default);check(Read(legacy)==legacyText,"legacy Windows default encoding is retained");
   string binary=Path.Combine(fixtures,"binary.txt");File.WriteAllBytes(binary,new byte[]{0,1,2,0,4,5,6,0,255,254});check(Failure(()=>Read(binary)) is InvalidDataException,"binary disguised as text is rejected");
   string cut=Path.Combine(fixtures,"cut.txt");File.WriteAllText(cut,new string('x',DocumentContent.MaxOutputCharacters+100),new UTF8Encoding(false));result=DocumentContent.Read(cut);check(result.Text.Length==DocumentContent.MaxOutputCharacters&&result.Truncated&&result.Limitation.Contains("前面部分"),"output is capped with explicit truncated notice");
   string prefix=Path.Combine(fixtures,"utf8-prefix.txt");File.WriteAllText(prefix,new string('x',DocumentContent.MaxTextReadBytes-1)+"中文",new UTF8Encoding(false));result=DocumentContent.Read(prefix);check(result.EncodingName=="utf-8"&&result.Truncated,"multibyte character split at prefix does not change valid UTF-8 to ANSI");
   string oversized=Path.Combine(fixtures,"oversized.txt");using(var file=new FileStream(oversized,FileMode.Create,FileAccess.Write))file.SetLength(DocumentContent.MaxTextFileBytes+1);check(Failure(()=>Read(oversized)) is NotSupportedException,"oversized text is refused before allocating contents");
   string rawXml=Path.Combine(fixtures,"literal.xml");File.WriteAllText(rawXml,"<!DOCTYPE x SYSTEM 'https://example.invalid/no-fetch'><x>&secret;</x>");check(Read(rawXml).Contains("https://example.invalid/no-fetch"),"standalone XML is literal text and never parses or fetches entities");
   string csv=Path.Combine(fixtures,"literal.csv");File.WriteAllText(csv,"name,formula\r\nA,=HYPERLINK(\"https://example.invalid\")");check(Read(csv).Contains("=HYPERLINK"),"CSV retains formulas as inert plain text");
   using(var cancellation=new CancellationTokenSource()){cancellation.Cancel();check(Failure(()=>DocumentContent.Read(text,cancellation.Token)) is OperationCanceledException,"cancelled sync preview is not started");check(Failure(()=>DocumentContent.OpenAsync(text,cancellation.Token).GetAwaiter().GetResult()) is OperationCanceledException,"cancelled async preview does not occupy a decoder slot");}
   check(DocumentContent.OpenAsync(text,CancellationToken.None).GetAwaiter().GetResult().Text==Read(text),"async content preview matches sync output");
   string word=Path.Combine(fixtures,"sample.docx");Package(word,"word/document.xml","<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:body><w:p><w:r><w:t>Hello </w:t></w:r><w:r><w:t>中文</w:t><w:tab/><w:t>content</w:t><w:br/><w:t>new line</w:t></w:r></w:p><w:p><w:r><w:instrText>DO NOT SHOW</w:instrText><w:t>Second paragraph</w:t></w:r></w:p></w:body></w:document>");original=File.ReadAllBytes(word);result=DocumentContent.Read(word);
   check(result.Text=="Hello 中文\tcontent\nnew line\nSecond paragraph","Word content includes paragraphs, tabs and line breaks");
   check(!result.Text.Contains("DO NOT SHOW")&&result.Limitation.Contains("不保留版式")&&result.Limitation.Contains("不执行宏"),"Word fields are not executed or shown as text and fidelity limit is explicit");
   check(original.SequenceEqual(File.ReadAllBytes(word)),"Office content preview never rewrites source archive");
   string dtd=Path.Combine(fixtures,"dtd.docx");Package(dtd,"word/document.xml","<!DOCTYPE document [<!ENTITY x SYSTEM 'file:///C:/do-not-read.txt'>]><document><p><t>&x;</t></p></document>");check(Failure(()=>Read(dtd)) is InvalidDataException,"Office XML DTD and external entities are prohibited");
   string corrupt=Path.Combine(fixtures,"corrupt.docx");File.WriteAllText(corrupt,"this is not a zip archive");check(Failure(()=>Read(corrupt)) is InvalidDataException,"corrupt document archive is reported without content allocation");
   string missing=Path.Combine(fixtures,"missing.docx");Package(missing,"other.xml","<x/>");check(Failure(()=>Read(missing)) is InvalidDataException,"missing mandatory document part is reported");
   string tooMany=Path.Combine(fixtures,"many.docx");using(var file=new FileStream(tooMany,FileMode.Create,FileAccess.Write))using(var zip=new ZipArchive(file,ZipArchiveMode.Create))for(int i=0;i<=DocumentContent.MaxPackageEntries;i++)zip.CreateEntry("entry"+i);check(Failure(()=>Read(tooMany)) is NotSupportedException,"archive entry count is bounded");
   string forgedCount=Path.Combine(fixtures,"forged-count.docx");var forgedBytes=File.ReadAllBytes(tooMany);forgedBytes[forgedBytes.Length-14]=1;forgedBytes[forgedBytes.Length-13]=0;forgedBytes[forgedBytes.Length-12]=1;forgedBytes[forgedBytes.Length-11]=0;File.WriteAllBytes(forgedCount,forgedBytes);check(Failure(()=>Read(forgedCount)) is NotSupportedException,"actual central-directory count is bounded before ZipArchive allocations even if advertised count is forged");
   string wrongCount=Path.Combine(fixtures,"wrong-count.docx");forgedBytes=File.ReadAllBytes(word);forgedBytes[forgedBytes.Length-14]=0;forgedBytes[forgedBytes.Length-13]=0;forgedBytes[forgedBytes.Length-12]=0;forgedBytes[forgedBytes.Length-11]=0;File.WriteAllBytes(wrongCount,forgedBytes);check(Failure(()=>Read(wrongCount)) is InvalidDataException,"mismatched ZIP directory count is refused");
   string metadataBomb=Path.Combine(fixtures,"metadata-bomb.docx");using(var file=new FileStream(metadataBomb,FileMode.Create,FileAccess.Write))using(var zip=new ZipArchive(file,ZipArchiveMode.Create))for(int i=0;i<65;i++)zip.CreateEntry(new string('n',65000)+i);check(Failure(()=>Read(metadataBomb)) is NotSupportedException,"central-directory metadata bytes are capped before ZipArchive allocations");
   string duplicate=Path.Combine(fixtures,"duplicate.docx");Package(duplicate,"word/document.xml","<x/>","WORD/document.xml","<x/>");check(Failure(()=>Read(duplicate)) is InvalidDataException,"ambiguous duplicate archive names are refused");
   string bigPart=Path.Combine(fixtures,"big-part.docx");Package(bigPart,"word/document.xml","<document><p><t>"+new string('x',(int)DocumentContent.MaxXmlPartBytes)+"</t></p></document>");check(Failure(()=>Read(bigPart)) is NotSupportedException,"oversized uncompressed XML part is refused before decompression");
   string bomb=Path.Combine(fixtures,"bomb.docx");Package(bomb,"word/document.xml","<document><p><t>"+new string('x',700000)+"</t></p></document>");check(Failure(()=>Read(bomb)) is InvalidDataException,"suspicious extreme compression ratio is refused");
   string totalBomb=Path.Combine(fixtures,"total-bomb.pptx");using(var file=new FileStream(totalBomb,FileMode.Create,FileAccess.Write))using(var zip=new ZipArchive(file,ZipArchiveMode.Create)){string part=new string(' ',(int)DocumentContent.MaxXmlPartBytes-100)+"<slide><p/></slide>";for(int i=1;i<=5;i++)using(var writer=new StreamWriter(zip.CreateEntry("ppt/slides/slide"+i+".xml",CompressionLevel.NoCompression).Open(),new UTF8Encoding(false)))writer.Write(part);}check(Failure(()=>Read(totalBomb)) is NotSupportedException,"combined XML read budget cannot be bypassed with multiple individually permitted parts");
   string excel=Path.Combine(fixtures,"sample.xlsx");Package(excel,
    "xl/workbook.xml","<workbook xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets><sheet name='Budget' r:id='rId1'/><sheet name='Notes' r:id='rId2'/></sheets></workbook>",
    "xl/_rels/workbook.xml.rels","<Relationships><Relationship Id='rId1' Target='worksheets/sheet1.xml'/><Relationship Id='rId2' Target='/xl/worksheets/sheet2.xml'/><Relationship Id='remote' Target='https://example.invalid/remote.xml' TargetMode='External'/></Relationships>",
    "xl/sharedStrings.xml","<sst><si><t>Shared 中文</t></si><si><r><t>Rich </t></r><r><t>text</t></r></si></sst>",
    "xl/worksheets/sheet1.xml","<worksheet><sheetData><row r='1'><c r='A1' t='s'><v>0</v></c><c r='XFD1048576' t='n'><v>42</v></c><c r='Z1' t='b'><v>1</v></c></row><row r='2'><c r='C2' t='inlineStr'><is><t>Inline</t></is></c><c r='D2'><f>RUN_NOTHING()</f><v>3</v></c><c r='E2' t='s'><v>1</v></c></row></sheetData></worksheet>",
    "xl/worksheets/sheet2.xml","<worksheet><sheetData><row><c r='B4' t='s'><v>999999</v></c></row></sheetData></worksheet>");result=DocumentContent.Read(excel);
   check(result.Text.Contains("【Budget】")&&result.Text.Contains("【Notes】"),"Excel preserves worksheet names in workbook order");
   check(result.Text.Contains("A1: Shared 中文")&&result.Text.Contains("E2: Rich text")&&result.Text.Contains("C2: Inline"),"Excel reads shared, rich and inline strings");
   check(result.Text.Contains("XFD1048576: 42")&&result.Text.Length<500,"sparse Excel coordinates do not allocate empty million-row tables");
   check(result.Text.Contains("Z1: TRUE")&&result.Text.Contains("D2: 3")&&!result.Text.Contains("RUN_NOTHING"),"Excel uses cached formula results and never executes formulas");
   check(result.Text.Contains("文字索引超出预览范围")&&result.Limitation.Contains("不重新计算公式"),"invalid shared-string index is safely labelled");
   string externalSheet=Path.Combine(fixtures,"external-sheet.xlsx");Package(externalSheet,"xl/workbook.xml","<workbook xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets><sheet name='Remote' r:id='r1'/></sheets></workbook>","xl/_rels/workbook.xml.rels","<Relationships><Relationship Id='r1' Target='https://example.invalid/sheet.xml' TargetMode='External'/></Relationships>");check(Failure(()=>Read(externalSheet)) is InvalidDataException,"external worksheet relationships are never loaded");
   string traversingSheet=Path.Combine(fixtures,"traversing-sheet.xlsx");Package(traversingSheet,"xl/workbook.xml","<workbook xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets><sheet name='Escaped' r:id='r1'/></sheets></workbook>","xl/_rels/workbook.xml.rels","<Relationships><Relationship Id='r1' Target='../../outside.xml'/></Relationships>","outside.xml","<worksheet/>");check(Failure(()=>Read(traversingSheet)) is InvalidDataException,"worksheet path traversal cannot escape package worksheet scope");
   string slides=Path.Combine(fixtures,"sample.pptx");Package(slides,"ppt/slides/slide10.xml","<slide><p><t>TENTH</t></p></slide>","ppt/slides/slide2.xml","<slide><p><t>SECOND</t></p></slide>","ppt/slides/slide1.xml","<slide><p><t>FIRST</t></p></slide>","ppt/notesSlides/notesSlide1.xml","<notes><t>HIDDEN NOTES</t></notes>");result=DocumentContent.Read(slides);
   check(result.Text.IndexOf("FIRST",StringComparison.Ordinal)<result.Text.IndexOf("SECOND",StringComparison.Ordinal)&&result.Text.IndexOf("SECOND",StringComparison.Ordinal)<result.Text.IndexOf("TENTH",StringComparison.Ordinal),"slides are ordered numerically rather than lexical slide10-before-slide2");
   check(result.Text.Contains("第 10 页")&&!result.Text.Contains("HIDDEN NOTES"),"slide preview labels pages without mixing hidden speaker notes");
   string manySlides=Path.Combine(fixtures,"many-slides.pptx");var slidePairs=new List<string>();for(int i=1;i<=DocumentContent.MaxPages+1;i++){slidePairs.Add("ppt/slides/slide"+i+".xml");slidePairs.Add("<slide><p><t>PAGE-"+i+"</t></p></slide>");}Package(manySlides,slidePairs.ToArray());result=DocumentContent.Read(manySlides);check(result.Truncated&&result.Text.Contains("PAGE-64")&&!result.Text.Contains("PAGE-65"),"slide page count is capped with a truncated result");
   string odfXml="<office:document-content xmlns:office='urn:oasis:names:tc:opendocument:xmlns:office:1.0' xmlns:text='urn:oasis:names:tc:opendocument:xmlns:text:1.0' xmlns:table='urn:oasis:names:tc:opendocument:xmlns:table:1.0' xmlns:draw='urn:oasis:names:tc:opendocument:xmlns:drawing:1.0'><office:scripts><text:p>NO SCRIPT CONTENT</text:p></office:scripts><office:body><office:text><text:h>Heading</text:h><text:p>ODF <text:span>中文</text:span><text:s text:c='2'/>text<text:tab/>tab<text:line-break/>line</text:p><table:table table:name='Sheet'><table:table-row><table:table-cell><text:p>Cell</text:p></table:table-cell></table:table-row></table:table><draw:page><text:p>Slide</text:p></draw:page></office:text></office:body></office:document-content>";
   foreach(string extension in new[]{".odt",".ods",".odp"}){string odf=Path.Combine(fixtures,"sample"+extension);Package(odf,"content.xml",odfXml);result=DocumentContent.Read(odf);check(result.Text.Contains("Heading\nODF 中文  text\ttab\nline")&&!result.Text.Contains("NO SCRIPT CONTENT"),"ODF body text excludes scripts for "+extension);check(result.Text.Contains("【Sheet】")&&result.Text.Contains("第 1 页")&&result.Limitation.Contains("不"),"ODF table/slide sections are described for "+extension);}
   string emptyOdf=Path.Combine(fixtures,"empty.odt");Package(emptyOdf,"content.xml","<x/>");check(Failure(()=>Read(emptyOdf)) is InvalidDataException,"ODF without document body is rejected");
   check(Failure(()=>Read(Path.Combine(fixtures,"absent.txt"))) is FileNotFoundException,"missing document propagates a readable file-not-found failure");
   check(Failure(()=>Read(Path.Combine(fixtures,"anything.html"))) is NotSupportedException,"HTML cannot reach content preview through a direct call");
  }
 }
}
